import java.util.*;
public class HomeApplianceEnergyReport {static double power(String a){return switch(a){case "FRIDGE"->150;case "AC"->1500;case "TV"->100;case "WASHER"->500;default->throw new IllegalArgumentException("Unknown appliance: "+a);};}public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();double totalUnits=0,totalCost=0;for(int i=0;i<n;i++){String a=sc.next();double hours=sc.nextDouble();boolean saver=sc.nextBoolean();double units=power(a)*hours/1000.0;if(saver)units*=.75;double cost=units*8;System.out.printf("%s: Units=%.2f Cost=%.2f%n",a,units,cost);totalUnits+=units;totalCost+=cost;}System.out.printf("Total Units=%.2f Total Cost=%.2f%n",totalUnits,totalCost);}}
